import{_ as d,o as e,c as o,ae as r}from"./chunks/framework.Dwq5SdLE.js";const u=JSON.parse('{"title":"vjson","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),a={name:"index.md"};function n(c,t,i,l,s,h){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="vjson" tabindex="-1">vjson <a class="header-anchor" href="#vjson" aria-label="Permalink to &quot;vjson&quot;">​</a></h1><p>vjson 是一个 <strong>以 JSON 格式描述 Vue 组件、运行时（runtime）实时渲染</strong> 的渲染引擎。它无需经过编译、构建流程，即可将 JSON 动态转换为标准 Vue 组件，实现&quot;数据即页面、变更即生效&quot;。</p><p>并配套提供 <strong>可视化编辑器</strong>（@vjson/editor），支持节点树编辑、scriptSetup 片段管理、样式编辑与实时预览。</p><h2 id="monorepo-结构" tabindex="-1">monorepo 结构 <a class="header-anchor" href="#monorepo-结构" aria-label="Permalink to &quot;monorepo 结构&quot;">​</a></h2><table tabindex="0"><thead><tr><th>包</th><th>说明</th></tr></thead><tbody><tr><td><code>@vjson/core</code></td><td>渲染引擎核心：vjson 校验、代码生成、动态编译、组件缓存</td></tr><tr><td><code>@vjson/editor</code></td><td>可视化编辑器：节点树 / 属性面板 / scriptSetup / 样式 + 实时预览</td></tr><tr><td><code>@vjson/play</code></td><td>功能验证应用（playground）</td></tr><tr><td><code>@vjson/doc</code></td><td>文档站点（本站）</td></tr></tbody></table><h2 id="核心能力" tabindex="-1">核心能力 <a class="header-anchor" href="#核心能力" aria-label="Permalink to &quot;核心能力&quot;">​</a></h2><table tabindex="0"><thead><tr><th>特性</th><th>语法</th><th>说明</th></tr></thead><tbody><tr><td>静态属性</td><td><code>prop1: &#39;123&#39;</code></td><td>原样透传为组件/元素属性</td></tr><tr><td>动态属性</td><td><code>&#39;:prop2&#39;: &#39;dataRef.value&#39;</code></td><td>表达式在 setup 上下文中求值后传入</td></tr><tr><td>条件渲染</td><td><code>&#39;v-if&#39;: &#39;expr&#39;</code></td><td>表达式为真才渲染该节点</td></tr><tr><td>列表循环</td><td><code>&#39;v-for&#39;: &#39;(item, index, keyField) in list&#39;</code></td><td>支持 keyField 取循环节点 key</td></tr><tr><td>双向绑定</td><td><code>&#39;v-model&#39;: &#39;expr&#39;</code> / <code>&#39;v-model:title&#39;: &#39;expr&#39;</code></td><td>组件/原生元素自动适配</td></tr><tr><td>批量属性绑定</td><td><code>&#39;v-bind&#39;: &#39;attrsRef.value&#39;</code></td><td>求值对象合并进属性</td></tr><tr><td>显隐控制</td><td><code>&#39;v-show&#39;: &#39;expr&#39;</code></td><td>指令方式保留 DOM 仅切换 display</td></tr><tr><td>事件绑定</td><td><code>&#39;@click&#39;: &#39;handler&#39;</code></td><td>标识符引用与内联语句两种形式</td></tr><tr><td>插槽</td><td><code>children</code> + <code>slot</code> 字段</td><td>默认/具名/作用域插槽</td></tr><tr><td>动态业务逻辑</td><td><code>scriptSetup: [...]</code></td><td>字符串数组注入 setup 函数体</td></tr></tbody></table><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="./getting-started.html">快速上手</a></li><li><a href="./vjson-spec.html">vjson 数据结构规范</a></li><li><a href="./editor.html">编辑器使用手册</a></li></ul>',9)])])}const m=d(a,[["render",n]]);export{u as __pageData,m as default};
